<style>
@page { margin: 25px 30px; }
*{box-sizing:border-box}body{margin:0;background:#f5f4fa;color:#231b35;font:14px 'DejaVu Sans',Arial,sans-serif}a{color:#6d28d9}.report{max-width:1180px;margin:32px auto;padding:30px;background:#fff;border:1px solid #e8e2ef;border-radius:18px}.brand{color:#6d28d9;font-size:12px;font-weight:bold;letter-spacing:2px}.eyebrow{color:#756787;font-size:12px;margin:18px 0 4px}h1{font-size:28px;line-height:1.2;margin:10px 0}h2{font-size:18px;margin:28px 0 12px}p{line-height:1.6}.muted{color:#73677f}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid #e8e2ef;margin-bottom:20px}.button,button,select,input{font:inherit;padding:10px 14px;border:1px solid #d9d0e5;border-radius:9px;background:white;color:#432063}.button{text-decoration:none;display:inline-block}.button.primary{background:#6d28d9;color:#fff;border-color:#6d28d9}.badge{display:inline-block;border-radius:20px;padding:6px 10px;background:#f0e8fc;color:#5b21b6;font-size:12px}.notice{padding:14px;background:#fff7df;border-left:3px solid #d09a25;color:#755516;margin:16px 0;line-height:1.5}.totals{width:100%;border-collapse:collapse;margin:20px 0}.totals td{padding:15px 12px;background:#f7f3fd;border:1px solid #e9dff6;vertical-align:top}.totals small{display:block;color:#756787;margin-bottom:8px}.totals strong{font-size:20px}.table-wrap{overflow-x:auto}.details{width:100%;border-collapse:collapse;font-size:12px}.details th{text-align:left;background:#f4effa;color:#625172;padding:11px 8px;border-bottom:1px solid #dcd0e9}.details td{padding:11px 8px;border-bottom:1px solid #eee8f4;vertical-align:top}.details tr{page-break-inside:avoid}.details thead{display:table-header-group}.number{text-align:right!important;white-space:nowrap;font-variant-numeric:tabular-nums}.negative{color:#ab2546}.formula{background:#f7f3fd;padding:18px;border-radius:12px;line-height:1.7}.footer{border-top:1px solid #e8e2ef;margin-top:28px;padding-top:14px;font-size:11px;color:#83748e}label{font-size:12px}.filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.filters label{display:grid;gap:6px}
@media(max-width:640px){.report{margin:12px;padding:20px}.totals,.totals tbody,.totals tr{display:block}.totals td{display:inline-block;width:50%;min-height:95px}.totals strong{font-size:17px}h1{font-size:24px}.details{min-width:650px}.toolbar .button{flex:1;text-align:center}}
@media print{body{background:white}.report{max-width:none;margin:0;padding:0;border:0;border-radius:0}.no-print{display:none!important}.table-wrap{overflow:visible}.details{min-width:0}.totals td{display:table-cell}.totals,.totals tbody,.totals tr{display:table-row-group}h2{page-break-after:avoid}}
@if($pdf ?? false)
body{background:#fff;font-size:11px}.report{max-width:none;margin:0;padding:0;border:0}.no-print{display:none}h1{font-size:24px}.details{font-size:10px}.details td,.details th{padding:8px 6px}.totals strong{font-size:17px}.badge{font-size:10px}.footer{font-size:9px}
@endif
</style>
